import{U as e,W as t,nt as n,t as r}from"./chunks/framework.CPHJXLir.js";var i=JSON.parse(`{"title":"AL Syntax and Statement Structure","description":"","frontmatter":{},"headers":[],"relativePath":"your-first-al-programs/al-syntax-and-statement-structure.md","filePath":"your-first-al-programs/al-syntax-and-statement-structure.md"}`),a={name:`your-first-al-programs/al-syntax-and-statement-structure.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="al-syntax-and-statement-structure" tabindex="-1">AL Syntax and Statement Structure <a class="header-anchor" href="#al-syntax-and-statement-structure" aria-label="Permalink to “AL Syntax and Statement Structure”">​</a></h1><p>Like other programming languages, AL has rules for declaring variables, assigning values, calling methods, and grouping statements.</p><h2 id="statements" tabindex="-1">Statements <a class="header-anchor" href="#statements" aria-label="Permalink to “Statements”">​</a></h2><p>A <strong>statement</strong> is an instruction that tells AL to perform an action.</p><p>For example:</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Message(&#39;Hello, Business Central!&#39;);</span></span></code></pre></div><p>This displays a message to the user.</p><p>Another example:</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Total := 100 + 50;</span></span></code></pre></div><p>This assigns the value <code>150</code> to the variable <code>Total</code>.</p><p>Notice the following syntax rules:</p><ul><li><strong>Semicolons (<code>;</code>)</strong> separate statements.</li><li><strong>Single quotes (<code>&#39;</code>)</strong> enclose text literals.</li><li><strong>The assignment operator (<code>:=</code>)</strong> assigns a value to a variable.</li><li><strong>Parentheses (<code>()</code>)</strong> enclose method arguments.</li></ul><blockquote><p><strong>Important:</strong> Unlike C#, AL uses <code>:=</code> for assignment rather than <code>=</code>.</p></blockquote><h2 id="blocks-begin-and-end" tabindex="-1">Blocks: <code>begin</code> and <code>end</code> <a class="header-anchor" href="#blocks-begin-and-end" aria-label="Permalink to “Blocks: begin and end”">​</a></h2><p>In AL, <code>begin</code> and <code>end</code> group multiple statements into a single block.</p><p>This is particularly useful when a condition or loop needs to execute multiple statements.</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>begin</span></span>
<span class="line"><span>    Total := 100;</span></span>
<span class="line"><span>    Tax := 16;</span></span>
<span class="line"><span>    Message(&#39;Calculation completed.&#39;);</span></span>
<span class="line"><span>end;</span></span></code></pre></div><p>The statements inside the block execute sequentially, from top to bottom.</p><p>For example, when an <code>if</code> statement needs to execute multiple instructions, use a block:</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>if Total &gt; 100 then begin</span></span>
<span class="line"><span>    Tax := Total * 0.16;</span></span>
<span class="line"><span>    Message(&#39;Tax calculated.&#39;);</span></span>
<span class="line"><span>end;</span></span></code></pre></div><p>Without <code>begin</code> and <code>end</code>, only the first statement following <code>then</code> would belong to the <code>if</code> statement.</p><h2 id="variables-and-the-var-keyword" tabindex="-1">Variables and the <code>var</code> Keyword <a class="header-anchor" href="#variables-and-the-var-keyword" aria-label="Permalink to “Variables and the var Keyword”">​</a></h2><p>Variables temporarily hold values that your code can use and manipulate.</p><p>In AL, you declare variables using the <code>var</code> keyword.</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>var</span></span>
<span class="line"><span>    Total: Decimal;</span></span>
<span class="line"><span>    CustomerName: Text[100];</span></span>
<span class="line"><span>    IsApproved: Boolean;</span></span></code></pre></div><p>Here:</p><ul><li><code>Total</code> stores a decimal number.</li><li><code>CustomerName</code> stores text of up to 100 characters.</li><li><code>IsApproved</code> stores a Boolean value (<code>true</code> or <code>false</code>).</li></ul><p>The variable name comes before the colon (<code>:</code>), followed by its data type.</p><p><strong>Note:</strong> Variable declarations typically appear in a <code>var</code> section within an object or procedure.</p><h2 id="_5-comments" tabindex="-1">5. Comments <a class="header-anchor" href="#_5-comments" aria-label="Permalink to “5. Comments”">​</a></h2><p>Comments explain code to developers and are ignored when the program executes.</p><p>AL supports single-line comments using <code>//</code>.</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>// Calculate the total including tax</span></span>
<span class="line"><span>Total := Subtotal + Tax;</span></span></code></pre></div><p>You can also use block comments in al:</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/* This is also a comment */</span></span>
<span class="line"><span>Total := Subtotal + Tax;</span></span></code></pre></div><p>Use comments to explain <em>why</em> something is being done when the code alone doesn&#39;t make it obvious.</p><h2 id="case-sensitivity" tabindex="-1">Case Sensitivity <a class="header-anchor" href="#case-sensitivity" aria-label="Permalink to “Case Sensitivity”">​</a></h2><p>AL is case-insensitive, meaning identifiers and keywords can generally be written using different capitalization without changing their meaning.</p><p>For example, <code>Message</code> and <code>MESSAGE</code> refer to the same built-in method.</p><p>However, consistent capitalization improves readability. By convention, AL keywords are written in lowercase, while data types and method names commonly use PascalCase.</p><h2 id="further-reading" tabindex="-1">Further Reading <a class="header-anchor" href="#further-reading" aria-label="Permalink to “Further Reading”">​</a></h2><ul><li><a href="https://learn.microsoft.com/en-us/dynamics365/business-central/dev-itpro/developer/devenv-al-simple-statements" target="_blank" rel="noreferrer">AL Simple Statements</a></li><li><a href="https://learn.microsoft.com/en-us/dynamics365/business-central/dev-itpro/developer/devenv-al-control-statements" target="_blank" rel="noreferrer">AL Control Statements</a></li><li><a href="https://learn.microsoft.com/en-us/dynamics365/business-central/dev-itpro/developer/devenv-programming-in-al" target="_blank" rel="noreferrer">Programming in AL</a></li></ul><h2 id="key-takeaway" tabindex="-1">Key Takeaway <a class="header-anchor" href="#key-takeaway" aria-label="Permalink to “Key Takeaway”">​</a></h2><p>AL code consists of statements that perform actions. Semicolons separate statements, <code>:=</code> assigns values, and <code>begin</code> and <code>end</code> group multiple statements into a block. Understanding these basic rules makes it easier to read and write AL code.</p>`,44)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};